const form = document.querySelector('form') || document.body;
const els = Array.from(document.querySelectorAll('input, select, textarea, button, label'));
els.map(e => ({tag: e.tagName, type: e.type, name: e.name, id: e.id, placeholder: e.placeholder, ariaLabel: e.getAttribute('aria-label'), value: e.value, text: (e.textContent||'').slice(0,40)}));
EOF

